local ActionDarkDreamResultShareShowDialog = Class('ActionDarkDreamResultShareShowDialog',GachaponShareResultPanel)
local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")
local TeamCellLuaPath = "Game.UI.FightReady.ChaoticRecall.Cell.ActionDarkDreamCommonTeamNodeCell"
---@type TeamComponent
local teamComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TeamComponent)

function ActionDarkDreamResultShareShowDialog:__init()

end

function ActionDarkDreamResultShareShowDialog:__delete()

end

function ActionDarkDreamResultShareShowDialog:Awake()
    KTool.SetActive(self.controller.gameObject,false)
    GachaponShareResultPanel.Awake(self)
    self:RefreshInfo()
end

function ActionDarkDreamResultShareShowDialog:RefreshInfo()
    local info = CfUtils.CookieLoad("ActionDarkDreamMainDialogGroupIdAndIndex")
    local info = string.split(info,"_")
    local groupId = info[1]
    local index = checkNumber(info[2])
    local dojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
    self:SetTitleAndTeamInfo(groupId,index,dojo)
end

function ActionDarkDreamResultShareShowDialog:SetTeamInfo(index,dojo)
    local curNodeData = dojo:GetNodeData(index)
    local teamInfo
    for i = #curNodeData, 1, -1 do
        local data = curNodeData[i]
        for j = #data, 1, -1 do
            if data[j].passed == 1 then
                teamInfo = data[j].teamInfo
                break
            end
        end
        if not isNull(teamInfo) then
            break
        end
    end

    if isNull(teamInfo) then
        KTool.SetActive(self.TeamNode1.gameObject,false)
        KTool.SetActive(self.TeamNode2.gameObject,false)
        return
    end

    for i = 1, 2 do
        local teamNode = self["TeamNode"..i]
        if teamInfo[i] then
            KTool.SetActive(teamNode.gameObject,true)
            ---@type ActionDarkDreamCommonTeamNodeCell
            local teamEnv = CfUtils.GetLuaScr(teamNode,TeamCellLuaPath)
            if teamEnv then
                teamEnv:SetParameters(i,false)
                local power = teamComponent:GetTeamFightingPower(teamInfo[i].cardsInfo,teamInfo[i].catsInfo)
                teamInfo[i].combatValue = power
                teamEnv:UpdateTeamInfo(teamInfo[i])
            end
        else
            KTool.SetActive(teamNode.gameObject,false)
        end
    end

    local card = teamInfo[1].cardsInfo[1]
    if not isNull(card) then
        local cardId = card.cardId
        local goodsType = GoodsUtils.GetIdType(cardId)
        local skinId = 0
        if goodsType == Constants.IDType.CardSkin then
            ---@type CardSkinVo
            local skinVo = CfUtils.GetCfVo(AutoIds.IdSetting113 , "CardSkinVo" ,cardId)
            cardId = skinVo.roleId
            skinId = cardId
        end
        ---@type CardVo
        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardId)
        local skinId = skinId > 0 and skinId or cardVo.defaultSkin

        -- 卡牌立绘
        ---@type CardSkinVo
        local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(skinId)
        self.BossDrawingNode:Execute(skinVo.skinId)


        -- 卡牌名称/角色名
        ---@type RolesVo
        local roleVo = CardConfMgr:GetInstance():GetRolesVo(cardVo.characterId) or {}
        -- 角色声优
        CfUtils.FillText(self.TxtCVName, localize('CV: _name_', {_name_ = cardVo.cv}))
        CfUtils.FillText(self.Desc, tostring(roleVo.name))
    end
    KTool.SetActive(self.controller.gameObject,true)
end

function ActionDarkDreamResultShareShowDialog:SetTitleAndTeamInfo(groupId,index,dojo)
    local vo = ChaoticRecallUtils.GetChaoticRecallTagVo(groupId)
    if not isNull(vo) then
        CfUtils.FillText(self.TxtTitle,vo.name)
        local title = vo.title
        if not isNull(title) and title ~= "" then
            CfUtils.FillText(self.TxtLv,vo.title)
            CfUtils.SetActive(self.TxtLv.gameObject,true)
        else
            CfUtils.SetActive(self.TxtLv.gameObject,false)
        end
    end
    CfUtils.FillImage(self.Bg,vo.background)
    local passStar = dojo:GetAllPassStar(index)
    CfUtils.FillText(self.TxtNumStar,passStar)
    self:SetTeamInfo(index,dojo)
end

function ActionDarkDreamResultShareShowDialog:OnInit(params)
    GachaponShareResultPanel.OnInit(self,params)
end

function ActionDarkDreamResultShareShowDialog:Start()
    GachaponShareResultPanel.Start(self)
end

function ActionDarkDreamResultShareShowDialog:SetInitCompleteCB(cb)
    CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
            cb()
        end)
    end))
end

function ActionDarkDreamResultShareShowDialog:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActionDarkDreamResultShareShowDialog